 $('#startFocusBtn').onclick=startFocus;$('#pauseFocusBtn').onclick=()=>{clearInterval(focusTimer);focusRunning=false};$('#resetFocusBtn').onclick=()=>{clearInterval(focusTimer);focusRunning=false;focusSeconds=1500;updateTimer()};
 $('#saveSettingsBtn').onclick=()=>{data.settings.name=$('#settingsName').value.trim()||'Estudante';data.settings.period=$('#settingsPeriod').value;data.settings.weeklyHours=Number($('#settingsHours').value)||20;data.settings.startTime=$('#settingsStart').value||'19:00';data.settings.endTime=$('#settingsEnd').value||'22:00';save();renderDashboard();alert('Perfil salvo.')};$('#resetDataBtn').onclick=()=>{if(confirm('Apagar todos os dados locais?')){localStorage.removeItem(STORAGE);location.reload()}};
 $('#smartPlanBtn').onclick=()=>{generatedPlan=[];$('#plannerPreview').textContent='Clique em “Gerar plano” para visualizar a proposta.';$('#applyPlanBtn').disabled=true;openModal('plannerModal')};$('#previewPlanBtn').onclick=generatePlan;$('#applyPlanBtn').onclick=applyPlan;
 $('#globalSearchBtn').onclick=()=>{openModal('searchModal');globalSearch()};$('#globalSearchInput').oninput=globalSearch;
 $('#startNextActionBtn').onclick=()=>{const a=nextAction();if(!a)return;if(a.taskId){$('#focusTaskSelect').value=a.taskId;$('#focusGoal').value=a.title}else{$('#focusGoal').value=a.title}nav('focus')};
 $('#focusTaskSelect').onchange=()=>{const t=data.tasks.find(x=>x.id===$('#focusTaskSelect').value);if(t)$('#focusGoal').value=t.title};
 document.addEventListener('change',e=>{const el=e.target.closest('[data-topic-progress]');if(el){const[sid,tid]=el.dataset.topicProgress.split('|'),s=subject(sid),t=s?.topics.find(x=>x.id===tid);if(t){t.progress=Math.max(0,Math.min(100,Number(el.value)||0));recalcSubject(s);save();renderSubjects();renderDashboard()}}});
